Definition chkr (m : mem) (p n : Z) : Prop :=
  acc asegs m p n
  /\ (forall i, 0 <= i < n -> exists w : word, ro_cells asegs m (al8 (shad (p + i))) [C8 w])
  /\ (region_in_mem p n /\ n <= 2^40).

