Definition ictx (m : mem) : Prop := icells m /\ icells_ms m /\ icells_sn m /\ m2s_cells m.

(* [comment removed for export] *)
Fixpoint in_rl (l : list (Z * Z)) (x : Z) : Prop :=
  match l with [] => False | (lo, hi) :: l' => (lo <= x < hi) \/ in_rl l' x end.
